export const PRIORITIES = {high:0,normal:1,low:2};
export function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function validDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(`${v}T12:00:00`);return !Number.isNaN(d.getTime())&&localDate(d)===v;}
export function normalizeTask(r){
 if(!r||typeof r!=='object'||typeof r.text!=='string'||!r.text.trim())throw Error('任务格式不正确');
 return {id:typeof r.id==='string'&&r.id?r.id:crypto.randomUUID(),text:r.text.trim().slice(0,200),done:r.done===true,priority:Object.hasOwn(PRIORITIES,r.priority)?r.priority:'normal',due:validDate(r.due)?r.due:'',category:typeof r.category==='string'?r.category.trim().slice(0,40):'',notes:typeof r.notes==='string'?r.notes.slice(0,5000):'',starred:r.starred===true,deleted:r.deleted===true,createdAt:Number.isFinite(r.createdAt)?r.createdAt:Date.now(),subtasks:Array.isArray(r.subtasks)?r.subtasks.slice(0,100).filter(s=>s&&typeof s.text==='string'&&s.text.trim()).map(s=>({text:s.text.trim().slice(0,200),done:s.done===true})):[]};
}
export function decodeTasks(data){const raw=Array.isArray(data)?data:data?.version===2?data.tasks:null;if(!Array.isArray(raw)||raw.length>10000)throw Error('请选择本工具导出的 JSON 备份（最多 10000 项任务）');const seen=new Set();return raw.map(r=>{const t=normalizeTask(r);if(seen.has(t.id))t.id=crypto.randomUUID();seen.add(t.id);return t;});}
export function matchesView(t,view,today=localDate()){if(view==='trash')return t.deleted;if(t.deleted)return false;if(view==='starred')return t.starred;if(view==='today')return !t.done&&t.due===today;if(view==='overdue')return !t.done&&!!t.due&&t.due<today;if(view==='upcoming'){const end=new Date(`${today}T12:00:00`);end.setDate(end.getDate()+7);return !t.done&&t.due>today&&t.due<=localDate(end);}return true;}
export function selectTasks(tasks,{view='all',filter='all',query='',category='',priority='',sort='created',today=localDate()}={}){const q=query.trim().toLocaleLowerCase();return tasks.filter(t=>matchesView(t,view,today)).filter(t=>filter==='all'||(filter==='done'?t.done:!t.done)).filter(t=>(!category||t.category===category)&&(!priority||t.priority===priority)&&(!q||`${t.text} ${t.notes} ${t.category}`.toLocaleLowerCase().includes(q))).sort((a,b)=>{if(sort==='due')return (a.due||'9999').localeCompare(b.due||'9999')||b.createdAt-a.createdAt;if(sort==='priority')return PRIORITIES[a.priority]-PRIORITIES[b.priority]||b.createdAt-a.createdAt;if(sort==='title')return a.text.localeCompare(b.text,'zh-CN');return b.createdAt-a.createdAt;});}
export function summary(tasks,today=localDate()){const active=tasks.filter(t=>!t.deleted),done=active.filter(t=>t.done).length;return {total:active.length,done,pending:active.length-done,today:active.filter(t=>!t.done&&t.due===today).length,progress:active.length?Math.round(done/active.length*100):0};}
export function mergeTasks(existing,incoming){const ids=new Set(existing.map(t=>t.id)),merged=[...existing];let added=0;for(const t of incoming){if(!ids.has(t.id)){merged.push(t);ids.add(t.id);added++;}}return {tasks:merged,added};}
export function csv(tasks){const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';return '\ufeff'+[['任务','状态','优先级','截止日期','分类','备注'],...tasks.filter(t=>!t.deleted).map(t=>[t.text,t.done?'已完成':'未完成',({high:'高',normal:'普通',low:'低'})[t.priority],t.due,t.category,t.notes])].map(row=>row.map(cell).join(',')).join('\r\n');}
